mapper.insert:

    SELECT
        'LGSK'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(LANGUAGE_SKILL_NO), LENGTH('LGSK' ) + 1)), 0) + 1, 6, '0')
    FROM LANGUAGE_SKILL

INSERT INTO LANGUAGE_SKILL (
	LANGUAGE_SKILL_NO
	, RESUME_NO
	, LANGUAGE_EXAM_CODE
	, LANGUAGE_CODE
	, LANGUAGE_EXAM_NAME
	, PASS_DATE
	, LANGUAGE_EXAM_TYPE
	, LANGUAGE_EXAM_SCORE
	, LANGUAGE_EXAM_LEVEL_CODE
) VALUES (
	#{languageSkillNo}
	, #{resumeNo}
	, #{languageExamCode}
	, #{languageCode}
	, #{languageExamName}
	, REPLACE(#{passDate}, '-', '')
	, #{languageExamType}
	, #{languageExamScore}
	, #{languageExamLevelCode}
)

mapper.update:
UPDATE LANGUAGE_SKILL 
   SET RESUME_NO = #{resumeNo}
       , LANGUAGE_EXAM_CODE = #{languageExamCode}
       , LANGUAGE_CODE = #{languageCode}
       , LANGUAGE_EXAM_NAME = #{languageExamName}
       , PASS_DATE = REPLACE(#{passDate}, '-', '')
       , LANGUAGE_EXAM_TYPE = #{languageExamType}
       , LANGUAGE_EXAM_SCORE = #{languageExamScore}
       , LANGUAGE_EXAM_LEVEL_CODE = #{languageExamLevelCode} 
 WHERE LANGUAGE_SKILL_NO = #{languageSkillNo}
